begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(16);
select extensions.has_table('public','twitter_financial_resolutions','resoluções imutáveis existem');
select extensions.has_table('public','twitter_financial_rules','regras financeiras futuras existem');
select extensions.ok(not has_function_privilege('authenticated','public.twitter_resolve_publication_attempt(uuid,twitter_financial_resolution,text,integer,text,text,text,integer,text,jsonb,boolean,text,uuid,text)','EXECUTE'),'authenticated não liquida diretamente');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('13100000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','twitter-231@example.com','',now(),now(),now());
insert into public.organizations(id,name,slug,created_by)values('23100000-0000-4000-8000-000000000001','Twitter 231','twitter-231','13100000-0000-4000-8000-000000000001');
insert into public.organization_members(organization_id,user_id,role,invited_by)values('23100000-0000-4000-8000-000000000001','13100000-0000-4000-8000-000000000001','admin','13100000-0000-4000-8000-000000000001');
create temporary table t231(identity_id uuid,connection_id uuid,profile_id uuid,epoch_id uuid,program_id uuid,reservation_id uuid)on commit drop;grant select,insert,update on t231 to service_role;insert into t231 default values;
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
do $$declare identity jsonb;connection jsonb;profile jsonb;reservation jsonb;pid uuid:=gen_random_uuid();begin identity:=public.twitter_register_identity_and_grant('23100000-0000-4000-8000-000000000001','zernio-231');connection:=public.twitter_upsert_connection_credentials('23100000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,'C','zp-231',repeat('encrypted',5),repeat('e',64),'api','scope','13100000-0000-4000-8000-000000000001','twitter-231@example.com');profile:=public.twitter_sync_profile_from_zernio('23100000-0000-4000-8000-000000000001',(connection->>'connectionId')::uuid,'za-231','xu-231','perfil231','Perfil',null,true,false,true,false,'free','[]');insert into public.twitter_programs(id,organization_id,schedule_kind,starts_at,ends_at,interval_minutes,total_requested,funded_count,unfunded_count,reserved_micros,rate_card_id,rate_card_version,review_digest,idempotency_key,created_by)select pid,'23100000-0000-4000-8000-000000000001','interval',now()-interval '5 minutes',now(),1,4,4,0,60000,id,version,repeat('b',64),'program-231','13100000-0000-4000-8000-000000000001'from public.twitter_rate_cards where active;reservation:=public.twitter_create_wallet_reservation('23100000-0000-4000-8000-000000000001',(identity->>'identityId')::uuid,(connection->>'connectionId')::uuid,1,'post_dm_create','publication',pid,60000,1,'reservation-231');insert into public.twitter_program_reservations values(pid,(reservation->>'reservationId')::uuid,(identity->>'identityId')::uuid,'post_dm_create');update t231 set identity_id=(identity->>'identityId')::uuid,connection_id=(connection->>'connectionId')::uuid,profile_id=(profile->>'profileId')::uuid,epoch_id=(profile->>'epochId')::uuid,program_id=pid,reservation_id=(reservation->>'reservationId')::uuid;end$$;
insert into public.twitter_publication_items(organization_id,program_id,profile_id,connection_epoch_id,connection_id,identity_id,slot_index,execute_at,content,weighted_characters,category,amount_micros,idempotency_key)select '23100000-0000-4000-8000-000000000001',program_id,profile_id,epoch_id,connection_id,identity_id,x,now()-interval '1 minute','resultado '||x,12,'post_dm_create',15000,'item-231-'||x from t231 cross join generate_series(0,3)x;
create temporary table claim231a as select * from public.twitter_claim_publication_items('worker-231',1);grant select on claim231a to service_role;
select public.twitter_resolve_publication_attempt((select attempt_id from claim231a),'local_failure','resolve-local-231',null,null,null,null,null,'falha antes da chamada','{}',false,null,null,null);
select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t231)),45000::bigint,'falha local libera hold');
select extensions.is((select status::text from public.twitter_item_holds where item_id=(select item_id from claim231a)),'released','hold local fica liberado');
create temporary table claim231b(item_id uuid,attempt_id uuid);grant select,insert on claim231b to service_role;
do $$declare iid uuid;aid uuid;begin select id into iid from public.twitter_publication_items where status='ready' order by slot_index limit 1;update public.twitter_publication_items set status='claimed',attempt_count=1,claimed_at=now(),claimed_by='worker-231' where id=iid;update public.twitter_item_holds set status='active',activated_at=now() where item_id=iid;insert into public.twitter_publication_attempts(organization_id,item_id,attempt_number,worker_id,idempotency_key)values('23100000-0000-4000-8000-000000000001',iid,1,'worker-231','attempt-231-b')returning id into aid;insert into claim231b values(iid,aid);end$$;
select public.twitter_start_external_attempt((select attempt_id from claim231b),'start-429-231');
select public.twitter_resolve_publication_attempt((select attempt_id from claim231b),'rate_limited','resolve-429-231',429,'rate_limit','req-429',null,30,'limite','{}',false,null,null,null);
select extensions.is((select status::text from public.twitter_publication_items where id=(select item_id from claim231b)),'retry','429 agenda retry');
select extensions.ok((select next_attempt_at>=timezone('utc',now())+interval '239 seconds' from public.twitter_publication_items where id=(select item_id from claim231b)),'retry respeita mínimo de quatro minutos');
select public.twitter_resolve_publication_attempt((select attempt_id from claim231b),'confirmed_failure','manual-release-429-231',429,'rate_limit','req-429',null,240,'retry cancelado','{}',true,'Operador confirmou ausência de cobrança','13100000-0000-4000-8000-000000000001','twitter-231@example.com');
select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t231)),30000::bigint,'retry confirmado sem cobrança devolve hold');
create temporary table claim231c(item_id uuid,attempt_id uuid);grant select,insert on claim231c to service_role;
do $$declare iid uuid;aid uuid;begin select id into iid from public.twitter_publication_items where status='ready' order by slot_index limit 1;update public.twitter_publication_items set status='claimed',attempt_count=1,claimed_at=now(),claimed_by='worker-231' where id=iid;update public.twitter_item_holds set status='active',activated_at=now() where item_id=iid;insert into public.twitter_publication_attempts(organization_id,item_id,attempt_number,worker_id,idempotency_key)values('23100000-0000-4000-8000-000000000001',iid,1,'worker-231','attempt-231-c')returning id into aid;insert into claim231c values(iid,aid);end$$;
select public.twitter_start_external_attempt((select attempt_id from claim231c),'start-unknown-231');
select public.twitter_resolve_publication_attempt((select attempt_id from claim231c),'outcome_unknown','unknown-231',504,'timeout','req-u',null,null,'resultado incerto','{}',false,null,null,null);
select extensions.is((select status::text from public.twitter_item_holds where item_id=(select item_id from claim231c)),'outcome_unknown','incerto mantém hold');
select extensions.is((select reserved_micros from public.twitter_wallets where identity_id=(select identity_id from t231)),30000::bigint,'incerto não devolve nem debita');
select public.twitter_resolve_publication_attempt((select attempt_id from claim231c),'published','manual-published-231',200,'manual','req-u','post-u',null,'confirmado manualmente','{"proof":true}',true,'Post remoto conferido pelo operador','13100000-0000-4000-8000-000000000001','twitter-231@example.com');
select extensions.is((select posted_balance_micros from public.twitter_wallets where identity_id=(select identity_id from t231)),11985000::bigint,'resolução manual liquida uma vez');
select extensions.is((select status::text from public.twitter_item_holds where item_id=(select item_id from claim231c)),'settled','hold incerto vira liquidado');
select public.twitter_resolve_publication_attempt((select attempt_id from claim231c),'published','manual-published-231',200,'manual','req-u','post-u',null,'replay','{}',true,'Post remoto conferido pelo operador','13100000-0000-4000-8000-000000000001','twitter-231@example.com');
select extensions.is((select count(*)::bigint from public.twitter_wallet_ledger where idempotency_key='manual-published-231:debit'),1::bigint,'replay não duplica débito');
select extensions.throws_ok($$update public.twitter_financial_resolutions set justification='alterada'$$,'55000','Registro financeiro imutável.','resolução é imutável');
select extensions.is((select count(*)::bigint from public.twitter_publication_items where status='claimed'),0::bigint,'nenhum claim cego após resultado incerto');
select extensions.is((select count(*)::bigint from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_class f on f.oid=c.confrelid where t.relname like 'twitter_%'and f.relname in('instagram_profiles','publication_items')),0::bigint,'nenhuma FK operacional Instagram');
select jsonb_build_object('finish',(select jsonb_agg(v)from extensions.finish()v),'wallets',(select count(*)from public.twitter_wallets),'ledgerDebits',(select count(*)from public.twitter_wallet_ledger where entry_kind='debit')) diagnostics;
rollback;
